def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def parsear_duracion(s):
    minutos = 0
    if 'h' in s:
        horas = int(s.split('h')[0])
        minutos += horas * 60
    if 'm' in s:
        minutos += int(s.split('m')[0].split('h')[-1])
    return minutos

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    izquierda, derecha = 0, len(lista) - 1
    while izquierda <= derecha:
        medio = (izquierda + derecha) // 2
        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            izquierda = medio + 1
        else:
            derecha = medio - 1
    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor = item[clave]
        if valor not in resultado:
            resultado[valor] = []
        resultado[valor].append(item)
    return resultado

def contar_palabras(texto):
    import string
    texto = texto.lower()
    texto = texto.translate(str.maketrans('', '', string.punctuation))
    palabras = texto.split()
    contador = {}
    for palabra in palabras:
        contador[palabra] = contador.get(palabra, 0) + 1
    return contador

def rotar(lista, n):
    if not lista:
        return []
    largo = len(lista)
    n = n % largo
    return lista[-n:] + lista[:-n]

def desde_romano(s):
    valores = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    resultado = 0
    previo = 0

    for c in reversed(s):
        actual = valores[c]
        if actual >= previo:
            resultado += actual
        else:
            resultado -= actual
        previo = actual

    return resultado

def mayor_racha(lista):
    if not lista:
        return None

    max_elemento = lista[0]
    max_longitud = 1
    actual_elemento = lista[0]
    actual_longitud = 1

    for i in range(1, len(lista)):
        if lista[i] == actual_elemento:
            actual_longitud += 1
        else:
            if actual_longitud > max_longitud:
                max_longitud = actual_longitud
                max_elemento = actual_elemento
            actual_elemento = lista[i]
            actual_longitud = 1

    if actual_longitud > max_longitud:
        max_longitud = actual_longitud
        max_elemento = actual_elemento

    return (max_elemento, max_longitud)

def a_camel(s):
    palabras = s.split('_')
    return palabras[0].lower() + ''.join(palabra.capitalize() for palabra in palabras[1:])

def a_snake(s):
    result = ""
    for i, c in enumerate(s):
        if c.isupper():
            if i > 0 and result:
                result += "_"
            result += c.lower()
        else:
            result += c
    return result

def primos(n):
    if n < 2:
        return []
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    return [i for i in range(2, n + 1) if sieve[i]]

def mcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def fusionar(intervalos):
    if not intervalos:
        return []

    # Ordenar los intervalos por el inicio
    sorted_intervalos = sorted(intervalos, key=lambda x: x[0])

    resultado = [sorted_intervalos[0]]

    for actual_inicio, actual_fin in sorted_intervalos[1:]:
        ultimo_inicio, ultimo_fin = resultado[-1]

        # Si el intervalo actual se solapa o toca con el último del resultado
        if actual_inicio <= ultimo_fin:
            # Fusionar: actualizar el final del último intervalo
            resultado[-1] = (ultimo_inicio, max(ultimo_fin, actual_fin))
        else:
            # No se solapa, agregar el intervalo actual
            resultado.append((actual_inicio, actual_fin))

    return resultado

def comprimir(s):
    if not s:
        return s
    resultado = ""
    contador = 1
    caracter_actual = s[0]

    for i in range(1, len(s)):
        if s[i] == caracter_actual:
            contador += 1
        else:
            resultado += caracter_actual + (str(contador) if contador > 1 else "")
            caracter_actual = s[i]
            contador = 1

    resultado += caracter_actual + (str(contador) if contador > 1 else "")

    return resultado if len(resultado) < len(s) else s

def balanceado(s):
    pila = []
    parejas = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in '([{':
            pila.append(char)
        elif char in ')]}':
            if not pila or pila.pop() != parejas[char]:
                return False

    return len(pila) == 0

def transpuesta(m):
    if not m or not m[0]:
        return []
    return [[m[i][j] for i in range(len(m))] for j in range(len(m[0]))]

def raiz_digital(n):
    while n >= 10:
        suma = 0
        while n > 0:
            suma += n % 10
            n //= 10
        n = suma
    return n

def sin_duplicados(lista):
    vista = set()
    resultado = []
    for elemento in lista:
        if elemento not in vista:
            vista.add(elemento)
            resultado.append(elemento)
    return resultado

def n_esimo_mayor(lista, n):
    valores_distintos = sorted(set(lista), reverse=True)
    if n > len(valores_distintos):
        return None
    return valores_distintos[n - 1]

def formatear_bytes(n):
    unidades = ['B', 'KB', 'MB', 'GB']
    valor = n
    indice = 0
    while valor >= 1024 and indice < len(unidades) - 1:
        valor /= 1024
        indice += 1
    if indice == 0:
        return f"{int(valor)} {unidades[indice]}"
    else:
        return f"{valor:.1f} {unidades[indice]}"

def en_lotes(lista, tamano):
    if not lista:
        return []
    return [lista[i:i + tamano] for i in range(0, len(lista), tamano)]
